CREATE FUNCTION lead.user_id() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('lead.user_id',true),'')::uuid $$;
CREATE FUNCTION lead.user_email() RETURNS text LANGUAGE sql STABLE AS $$ SELECT lower(nullif(current_setting('lead.email',true),'')) $$;
CREATE FUNCTION lead.is_member(ws uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,lead AS $$ SELECT EXISTS(SELECT 1 FROM lead.memberships WHERE workspace_id=ws AND user_id=lead.user_id()) $$;
CREATE FUNCTION lead.is_admin(ws uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,lead AS $$ SELECT EXISTS(SELECT 1 FROM lead.memberships WHERE workspace_id=ws AND user_id=lead.user_id() AND role IN ('owner','admin')) $$;
CREATE FUNCTION lead.shares_workspace(other_user uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,lead AS $$ SELECT EXISTS(SELECT 1 FROM lead.memberships a JOIN lead.memberships b USING(workspace_id) WHERE a.user_id=lead.user_id() AND b.user_id=other_user) $$;
CREATE FUNCTION lead.create_workspace(workspace_name text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,lead AS $$ DECLARE ws uuid; BEGIN
 IF lead.user_id() IS NULL OR length(workspace_name)<1 OR length(workspace_name)>100 THEN RAISE EXCEPTION 'Invalid workspace'; END IF;
 IF (SELECT count(*) FROM lead.memberships WHERE user_id=lead.user_id() AND role='owner')>=10 THEN RAISE EXCEPTION 'Workspace limit reached'; END IF;
 INSERT INTO lead.workspaces(name) VALUES(workspace_name) RETURNING id INTO ws;
 INSERT INTO lead.memberships(workspace_id,user_id,role) VALUES(ws,lead.user_id(),'owner'); RETURN ws;
END $$;
CREATE FUNCTION lead.accept_invite(invite_hash text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,lead AS $$ DECLARE invitation lead.invites; BEGIN
 SELECT * INTO invitation FROM lead.invites WHERE token_hash=invite_hash AND email=lead.user_email() AND expires_at>now() FOR UPDATE;
 IF NOT FOUND OR lead.user_id() IS NULL THEN RAISE EXCEPTION 'Invitation is invalid or expired'; END IF;
 INSERT INTO lead.memberships(workspace_id,user_id,role) VALUES(invitation.workspace_id,lead.user_id(),'member') ON CONFLICT DO NOTHING;
 DELETE FROM lead.invites WHERE id=invitation.id; RETURN invitation.workspace_id;
END $$;
CREATE FUNCTION lead.pending_jobs() RETURNS TABLE(id uuid,workspace_id uuid) LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,lead AS $$ SELECT id,workspace_id FROM lead.jobs WHERE status='queued' AND (dispatched_at IS NULL OR dispatched_at<now()-interval '10 minutes') ORDER BY created_at LIMIT 30 $$;
CREATE FUNCTION lead.mark_dispatched(job_id uuid) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,lead AS $$ UPDATE lead.jobs SET dispatched_at=now() WHERE id=job_id AND status='queued' $$;
CREATE FUNCTION lead.job_identity(job_id uuid) RETURNS TABLE(user_id uuid,email text,workspace_id uuid) LANGUAGE sql SECURITY DEFINER SET search_path=pg_catalog,lead AS $$ SELECT j.actor_id,u.email,j.workspace_id FROM lead.jobs j JOIN lead.users u ON u.id=j.actor_id WHERE j.id=job_id $$;
ALTER TABLE lead.memberships ADD CONSTRAINT member_role CHECK(role IN ('owner','admin','member'));
ALTER TABLE lead.entries ADD CONSTRAINT entry_stage CHECK(stage IN ('New','Shortlisted','Contacted','Not a fit'));
ALTER TABLE lead.connections ADD CONSTRAINT connection_provider CHECK(provider IN ('serpapi','groq','firecrawl'));
ALTER TABLE lead.campaigns ADD CONSTRAINT campaign_tenant UNIQUE(id,workspace_id);
ALTER TABLE lead.businesses ADD CONSTRAINT business_tenant UNIQUE(id,workspace_id);
ALTER TABLE lead.entries ADD CONSTRAINT entry_tenant UNIQUE(id,workspace_id);
ALTER TABLE lead.jobs ADD CONSTRAINT job_tenant UNIQUE(id,workspace_id);
ALTER TABLE lead.entries ADD CONSTRAINT entry_campaign_tenant FOREIGN KEY(campaign_id,workspace_id) REFERENCES lead.campaigns(id,workspace_id) ON DELETE CASCADE;
ALTER TABLE lead.entries ADD CONSTRAINT entry_business_tenant FOREIGN KEY(business_id,workspace_id) REFERENCES lead.businesses(id,workspace_id) ON DELETE CASCADE;
ALTER TABLE lead.entries ADD CONSTRAINT entry_assignee FOREIGN KEY(workspace_id,assigned_to) REFERENCES lead.memberships(workspace_id,user_id);
ALTER TABLE lead.observations ADD CONSTRAINT observation_business_tenant FOREIGN KEY(business_id,workspace_id) REFERENCES lead.businesses(id,workspace_id) ON DELETE CASCADE;
ALTER TABLE lead.analyses ADD CONSTRAINT analysis_entry_tenant FOREIGN KEY(entry_id,workspace_id) REFERENCES lead.entries(id,workspace_id) ON DELETE CASCADE;
ALTER TABLE lead.jobs ADD CONSTRAINT job_campaign_tenant FOREIGN KEY(campaign_id,workspace_id) REFERENCES lead.campaigns(id,workspace_id) ON DELETE CASCADE;
ALTER TABLE lead.usage ADD CONSTRAINT usage_job_tenant FOREIGN KEY(job_id,workspace_id) REFERENCES lead.jobs(id,workspace_id);
CREATE INDEX entries_workspace ON lead.entries(workspace_id,campaign_id);
CREATE INDEX observations_business ON lead.observations(workspace_id,business_id,created_at DESC);
CREATE INDEX analyses_entry ON lead.analyses(workspace_id,entry_id,created_at DESC);
CREATE INDEX jobs_dispatch ON lead.jobs(status,dispatched_at);
CREATE INDEX usage_daily ON lead.usage(workspace_id,created_at);
ALTER TABLE lead.users ENABLE ROW LEVEL SECURITY;
CREATE POLICY users_read ON lead.users FOR SELECT TO lead_app USING(id=lead.user_id() OR lead.shares_workspace(id));
CREATE POLICY users_insert ON lead.users FOR INSERT TO lead_app WITH CHECK(id=lead.user_id() AND email=lead.user_email());
CREATE POLICY users_update ON lead.users FOR UPDATE TO lead_app USING(id=lead.user_id()) WITH CHECK(id=lead.user_id() AND email=lead.user_email());
ALTER TABLE lead.workspaces ENABLE ROW LEVEL SECURITY;
CREATE POLICY workspace_read ON lead.workspaces FOR SELECT TO lead_app USING(lead.is_member(id));
ALTER TABLE lead.memberships ENABLE ROW LEVEL SECURITY;
CREATE POLICY membership_read ON lead.memberships FOR SELECT TO lead_app USING(lead.is_member(workspace_id));
DO $$ DECLARE table_name text; BEGIN FOREACH table_name IN ARRAY ARRAY['campaigns','businesses','observations','entries','analyses','jobs','usage','views'] LOOP
 EXECUTE format('ALTER TABLE lead.%I ENABLE ROW LEVEL SECURITY',table_name);
 EXECUTE format('CREATE POLICY tenant_access ON lead.%I TO lead_app USING(lead.is_member(workspace_id)) WITH CHECK(lead.is_member(workspace_id))',table_name);
 END LOOP; END $$;
ALTER TABLE lead.connections ENABLE ROW LEVEL SECURITY;
CREATE POLICY connection_read ON lead.connections FOR SELECT TO lead_app USING(lead.is_member(workspace_id));
CREATE POLICY connection_write ON lead.connections FOR ALL TO lead_app USING(lead.is_admin(workspace_id)) WITH CHECK(lead.is_admin(workspace_id));
ALTER TABLE lead.invites ENABLE ROW LEVEL SECURITY;
CREATE POLICY invitation_admin ON lead.invites TO lead_app USING(lead.is_admin(workspace_id)) WITH CHECK(lead.is_admin(workspace_id));
REVOKE ALL ON SCHEMA lead FROM PUBLIC;
GRANT USAGE ON SCHEMA lead TO lead_app,lead_queue_access;
GRANT SELECT,INSERT,UPDATE,DELETE ON ALL TABLES IN SCHEMA lead TO lead_app;
REVOKE INSERT,UPDATE,DELETE ON lead.workspaces,lead.memberships FROM lead_app;
REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA lead FROM PUBLIC;
GRANT EXECUTE ON FUNCTION lead.user_id(),lead.user_email(),lead.is_member(uuid),lead.is_admin(uuid),lead.shares_workspace(uuid),lead.create_workspace(text),lead.accept_invite(text) TO lead_app;
GRANT EXECUTE ON FUNCTION lead.pending_jobs(),lead.mark_dispatched(uuid),lead.job_identity(uuid) TO lead_queue_access;
